<template>
  <view class="v7-today" data-testid="today-screen">
    <view class="v7-home-summary-card">
      <view class="v7-home-summary-head"><view><text class="v7-home-summary-title">{{ checkedToday ? '今天已完成打卡' : '今日计划待完成' }}</text><text class="v7-home-summary-copy">{{ checkedToday ? '按状态休息，不必为积分额外加量' : '完成 1 项有效运动即可打卡' }}</text></view><button data-testid="home-checkin" @tap="emit('checkin')">打卡日历 ›</button></view>
      <view class="v7-home-summary-numbers"><view><text>{{ weeklyDays }}<text>/7</text></text><text>本周训练</text></view><view><text>{{ minutes }}<text>分钟</text></text><text>今日运动</text></view><view><text>{{ streak }}<text>天</text></text><text>连续打卡</text></view></view>
    </view>
    <view v-if="mode === 'cardiac'" class="v7-home-plan-card">
      <view class="v7-home-plan-heading"><view><text>医院今日计划</text><text>来自{{ hospital }}的今日处方</text></view><text>{{ completedTasks }}/{{ tasks.length }}</text></view>
      <swiper class="v7-home-plan-swiper" :class="{ adjusted: !!adjustment }" :current="slide" data-testid="prescription-swiper" tabindex="0" role="region" aria-label="医院今日处方，左右切换项目" data-keyboard-carousel="prescription" @change="emit('slide', $event)">
        <swiper-item v-for="(task,index) in tasks" :key="task.key" data-testid="prescription-slide" :aria-hidden="slide !== index" :inert="slide !== index ? '' : undefined">
          <view class="v7-home-prescription-card prescription-card" data-testid="today-core-task">
            <image class="v7-home-plan-art" src="/static/replica-v7/baduanjin.png" mode="aspectFit" aria-label="医院今日计划运动插画" />
            <view class="v7-home-plan-copy"><text class="v7-home-status-pill">{{ task.completed ? '已完成' : '待完成' }}</text><text class="v7-home-plan-title">{{ task.item.project }}</text><text class="v7-home-plan-detail">{{ task.item.duration }} · {{ task.item.intensity }}</text><text class="v7-home-plan-detail">{{ task.item.frequency }}</text><button class="v7-home-task-primary task-primary" :disabled="!task.game" @tap="emit('start-task',task)">{{ !task.game ? '暂未适配' : task.completed ? '再次训练' : '开始今天的运动' }}</button></view>
            <text v-if="adjustment" class="v7-home-plan-adjustment">医生已确认：{{ adjustment }}</text>
          </view>
        </swiper-item>
      </swiper>
      <view v-if="tasks.length > 1" class="v7-home-plan-pagination" data-testid="prescription-pagination"><text>{{ slide + 1 }}/{{ tasks.length }} 项</text><button v-for="(task,index) in tasks" :key="task.key" :class="{selected:slide===index}" :aria-label="'查看第'+(index+1)+'项处方'" @tap="emit('slide',{detail:{current:index}})"><view /></button></view>
    </view>
    <view v-else class="v7-home-plan-card v7-home-public-plan" data-testid="public-exercise-picker">
      <view class="v7-home-plan-heading"><view><text>今天的运动</text><text>按兴趣与身体感受选择</text></view></view>
      <view class="v7-home-prescription-card" data-testid="today-core-task"><image class="v7-home-plan-art" :src="artFor(featured.id)" mode="aspectFit"/><view class="v7-home-plan-copy"><text class="v7-home-status-pill">自选运动</text><text class="v7-home-plan-title">{{ featured.title }}</text><text class="v7-home-plan-detail">{{ featured.duration }}</text><button class="v7-home-task-primary" data-testid="start-self-exercise" @tap="emit('exercise',featured.id)">开始今天的运动</button></view></view>
    </view>
    <button class="v7-home-week-card" data-testid="home-weekly" @tap="emit('weekly')"><view><text>本周路径</text><text>已完成 {{ weeklyDays }}/7 天</text></view><view class="v7-home-week-dots"><text v-for="day in days" :key="day.label" :class="{done:day.done,today:day.today}">{{ day.done ? '✓' : day.label }}</text></view><text class="v7-home-chevron">›</text></button>
    <view class="v7-home-more-heading"><view><text>更多运动</text><text>按今天的状态选择</text></view><button data-testid="home-exercises" @tap="emit('all-exercises')">全部运动 ›</button></view>
    <view class="v7-home-exercise-cards" data-testid="cardiac-self-exercise-picker">
      <button v-for="game in visibleGames" :key="game.id" :data-testid="'home-exercise-'+game.id" @tap="emit('exercise',game.id)"><view><text>{{ homeTitle(game.id) }}</text><text>{{ game.duration }}</text></view><image :src="artFor(game.id)" mode="aspectFill" /></button>
    </view>
  </view>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import type { ExerciseGame, ExerciseGameId, UserMode } from '@/lib/prototype-data';
import type { SharedPrescriptionItem } from '@/lib/shared-patient';
type Task = { key: string; item: SharedPrescriptionItem; game?: ExerciseGame; completed: boolean };
const props=defineProps<{ mode:UserMode;displayName:string;greeting:string;hospital:string;weeklyDays:number;minutes:number;streak:number;checkedToday:boolean;completedTasks:number;tasks:Task[];slide:number;adjustment:string;featured:ExerciseGame;games:ExerciseGame[];days:Array<{label:string;done:boolean;today:boolean}> }>();
const emit=defineEmits<{(e:'start-task',task:Task):void;(e:'exercise',id:ExerciseGameId):void;(e:'slide',event:{detail:{current:number}}):void;(e:'checkin'):void;(e:'weekly'):void;(e:'all-exercises'):void}>();
const visibleGames=computed(()=>['walking','stretch','resistance','balance'].map(id=>props.games.find(g=>g.id===id)).filter((g):g is ExerciseGame=>Boolean(g)));
function artFor(id?:string){return '/static/replica-v7/'+(['walking','stretch','resistance','balance','baduanjin'].includes(id||'')?id:id==='breathing'?'article-recovery':'growth-bird')+'.png'}
function homeTitle(id:string){return ({walking:'户外快走',stretch:'舒缓拉伸',resistance:'弹力带训练',balance:'平衡练习'} as Record<string,string>)[id]||id}
</script>

